package net.officefloor.hq.app.person;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.OneToMany;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Objects;
import net.officefloor.hq.app.history.History;

/** A person on a sheet, with a name and a dated grade (A, B or C): each grade they are given applies
 *  from a date, the first from the beginning of time. */
@Entity
@EntityListeners(History.class)
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades they were given, each from a date; the first has none. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "person_id", nullable = false)
    private List<PersonGrade> grades = new ArrayList<>();

    /** Their own terms in days, ahead of their grade's and the sheet's; null when they have none. */
    @Column(name = "terms")
    private Integer terms;

    /** Their contact, trimmed and lower-cased; null when they have none. Unique on the sheet. */
    @Column(name = "contact")
    private String contact;

    /** The date they are retired from; null while not retired. Set at all, they count as retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Their holds: an OPEN or PENDING claim dated within one, and bound by no statement, counts in no
     *  live total; their other claims still do. */
    @OneToMany(cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)
    @JoinColumn(name = "person_id", nullable = false)
        this.terms = terms;
    }

    public String getOriginSheet() {
        return originSheet;
    }

    public String getContact() {
        return contact;
    }

    public void setContact(String contact) {
        this.contact = contact;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
        String trimmed = alias.trim();
        String key = trimmed.toLowerCase(Locale.ROOT);
        int copy = (int) aliases.stream().filter(a -> a.getAlias().toLowerCase(Locale.ROOT).equals(key)).count();
        aliases.add(new PersonAlias(sheetId, trimmed, copy));
    }

    /** A copy of them for another sheet: every grade they were given (with its from-date), their terms,
     *  contact and aliases; not their holds. */
    public Person copyTo(String otherSheetId) {
        Person copy = new Person();
        copy.sheetId = otherSheetId;
        copy.name = name;
        grades.forEach(g -> copy.grades.add(new PersonGrade(g.getGrade(), g.getFromDate())));
        copy.terms = terms;
        copy.contact = contact;
        copy.originSheet = sheetId;
        aliases.forEach(a -> copy.aliases.add(new PersonAlias(otherSheetId, a.getAlias(), a.getAliasCopy())));
        return copy;
    }

    public Long getPosition() {
        return position;
    }

    public void setPosition(Long position) {
        this.position = position;
    }

    public long getVersion() {
        return version;
    }
}
    }

    /** Copy the people with their grades, holds, retirements, aliases and patrons; the new id of each. */
    private Map<Long, Long> copyPeople(String id, String target) {
        Map<Long, Long> ids = new LinkedHashMap<>();
        for (Map<String, Object> p : jdbc.queryForList("SELECT * FROM person WHERE sheet_id = ? ORDER BY id", id)) {
            long newId = insert("INSERT INTO person (sheet_id, name, version, retired_from, terms, contact,"
                    + " list_position, origin_sheet) VALUES (?, ?, 0, ?, ?, ?, ?, ?)", target, p.get("name"),
                    p.get("retired_from"), p.get("terms"), p.get("contact"), p.get("list_position"),
                    p.get("origin_sheet"));
            long oldId = ((Number) p.get("id")).longValue();
            ids.put(oldId, newId);
            jdbc.update("INSERT INTO person_grade (person_id, grade, from_date)"
                    + " SELECT ?, grade, from_date FROM person_grade WHERE person_id = ? ORDER BY id", newId, oldId);
            jdbc.update("INSERT INTO person_hold (person_id, from_date, to_date)"
                    + " SELECT ?, from_date, to_date FROM person_hold WHERE person_id = ? ORDER BY id", newId, oldId);
